import{_ as i,c as t,o as s,ae as o}from"./chunks/framework.DMK_uHmU.js";const p=JSON.parse('{"title":"AI Test Case Configuration Guide","description":"","frontmatter":{},"headers":[],"relativePath":"Administration/AI-Management/Test-Cases/test-cases.md","filePath":"Administration/AI-Management/Test-Cases/test-cases.md"}'),n={name:"Administration/AI-Management/Test-Cases/test-cases.md"};function a(l,e,r,u,c,h){return s(),t("div",null,e[0]||(e[0]=[o('<h1 id="ai-test-case-configuration-guide" tabindex="-1">AI Test Case Configuration Guide <a class="header-anchor" href="#ai-test-case-configuration-guide" aria-label="Permalink to &quot;AI Test Case Configuration Guide&quot;">​</a></h1><h2 id="table-of-contents" tabindex="-1">Table of Contents <a class="header-anchor" href="#table-of-contents" aria-label="Permalink to &quot;Table of Contents&quot;">​</a></h2><ul><li><a href="#ai-test-case-configuration-guide">AI Test Case Configuration Guide</a><ul><li><a href="#table-of-contents">Table of Contents</a></li><li><a href="#introduction">Introduction</a></li><li><a href="#accessing-test-case-configuration">Accessing Test Case Configuration</a></li><li><a href="#test-case-interface-overview">Test Case Interface Overview</a></li><li><a href="#ai-tuning-configuration">AI Tuning Configuration</a><ul><li><a href="#model-selection">Model Selection</a></li><li><a href="#system-instructions">System Instructions</a></li><li><a href="#response-parameters">Response Parameters</a></li></ul></li><li><a href="#parameter-controls">Parameter Controls</a><ul><li><a href="#randomness-temperature">Randomness (Temperature)</a></li><li><a href="#top-k">Top K</a></li><li><a href="#top-p-nucleus-sampling">Top P (Nucleus Sampling)</a></li><li><a href="#search-results">Search Results</a></li><li><a href="#minimum-score">Minimum Score</a></li></ul></li><li><a href="#managing-test-questions">Managing Test Questions</a><ul><li><a href="#adding-questions">Adding Questions</a></li><li><a href="#organizing-questions">Organizing Questions</a></li><li><a href="#removing-questions">Removing Questions</a></li></ul></li><li><a href="#test-case-operations">Test Case Operations</a><ul><li><a href="#saving-configurations">Saving Configurations</a></li><li><a href="#running-tests">Running Tests</a></li><li><a href="#comparing-results">Comparing Results</a></li><li><a href="#promoting-to-production">Promoting to Production</a></li></ul></li><li><a href="#best-practices">Best Practices</a></li><li><a href="#troubleshooting">Troubleshooting</a></li></ul></li></ul><h2 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;Introduction&quot;">​</a></h2><p>The AI Test Case system allows administrators to experiment with various AI settings and parameters without affecting production environments. This testing framework enables you to evaluate how changes to AI tuning will impact responses before deploying them to live systems. You can create test configurations, run comparative tests with sample questions, and promote successful configurations to production when satisfied with the results.</p><h2 id="accessing-test-case-configuration" tabindex="-1">Accessing Test Case Configuration <a class="header-anchor" href="#accessing-test-case-configuration" aria-label="Permalink to &quot;Accessing Test Case Configuration&quot;">​</a></h2><p>The Test Case Configuration is accessible to users with specific roles:</p><ul><li>Admin</li><li>Content</li><li>Manager</li></ul><p>This interface is typically found within the Knowledge Base management section or AI configuration areas of the platform.</p><h2 id="test-case-interface-overview" tabindex="-1">Test Case Interface Overview <a class="header-anchor" href="#test-case-interface-overview" aria-label="Permalink to &quot;Test Case Interface Overview&quot;">​</a></h2><p>The Test Case system consists of two main components:</p><ol><li><p><strong>AI Tuning Dialog</strong>: Configure AI model settings and parameters</p><ul><li>Model selection</li><li>System instructions</li><li>Response parameter tuning with visual controls</li></ul></li><li><p><strong>Questions Dialog</strong>: Manage test case questions</p><ul><li>Add and organize test questions</li><li>Run tests against configurations</li><li>Compare results between test and production</li></ul></li></ol><h2 id="ai-tuning-configuration" tabindex="-1">AI Tuning Configuration <a class="header-anchor" href="#ai-tuning-configuration" aria-label="Permalink to &quot;AI Tuning Configuration&quot;">​</a></h2><h3 id="model-selection" tabindex="-1">Model Selection <a class="header-anchor" href="#model-selection" aria-label="Permalink to &quot;Model Selection&quot;">​</a></h3><p>Select the foundation model that will power your test:</p><ol><li><p><strong>AI Foundation Model</strong> dropdown provides options:</p><ul><li><strong>Anthropic Claude</strong>: <ul><li>Haiku 3</li><li>Sonnet 3</li><li>Sonnet 3.5</li></ul></li><li><strong>Meta</strong>: <ul><li>Llama 3</li><li>Llama 3.1</li></ul></li></ul></li><li><p><strong>Model Selection Considerations</strong>:</p><ul><li>Different models have varying capabilities and costs</li><li>Selection affects response quality and processing time</li><li>Some models may be better suited for specific use cases</li></ul></li></ol><h3 id="system-instructions" tabindex="-1">System Instructions <a class="header-anchor" href="#system-instructions" aria-label="Permalink to &quot;System Instructions&quot;">​</a></h3><p>Configure how the AI behaves and responds:</p><ol><li><p><strong>System 1 - Role of assistant</strong>:</p><ul><li>Define the AI&#39;s role and capabilities</li><li>Set boundaries for what it can/cannot do</li><li>Provide guidance on tone and approach</li><li>Optional field with 4,000 character limit</li><li>Default instructions are used if left blank</li></ul></li><li><p><strong>System 2</strong> (hidden option):</p><ul><li>Controls output formatting</li><li>Can specify citation requirements</li><li>Sets output style (Markdown, HTML, etc.)</li><li>Not visible in the current interface version</li></ul></li></ol><h3 id="response-parameters" tabindex="-1">Response Parameters <a class="header-anchor" href="#response-parameters" aria-label="Permalink to &quot;Response Parameters&quot;">​</a></h3><p>Fine-tune how the AI generates responses through various parameters displayed as interactive knobs:</p><ol><li><strong>Parameter Controls</strong>: <ul><li>Each parameter has a visual dial/knob control</li><li>Knobs can be adjusted by dragging or clicking</li><li>Changes take effect after saving</li><li>Default values are pre-set for new tests</li></ul></li></ol><h2 id="parameter-controls" tabindex="-1">Parameter Controls <a class="header-anchor" href="#parameter-controls" aria-label="Permalink to &quot;Parameter Controls&quot;">​</a></h2><h3 id="randomness-temperature" tabindex="-1">Randomness (Temperature) <a class="header-anchor" href="#randomness-temperature" aria-label="Permalink to &quot;Randomness (Temperature)&quot;">​</a></h3><p>Controls creativity and variability in responses:</p><ol><li><p><strong>Knob Settings</strong>:</p><ul><li>Range: 1-20</li><li>Default: 1</li><li>Step: 1</li></ul></li><li><p><strong>Effect</strong>:</p><ul><li>Higher values (10-20): More creative, varied responses</li><li>Lower values (1-5): More consistent, predictable responses</li><li>Middle values (5-10): Balance between creativity and consistency</li></ul></li></ol><h3 id="top-k" tabindex="-1">Top K <a class="header-anchor" href="#top-k" aria-label="Permalink to &quot;Top K&quot;">​</a></h3><p>Controls diversity of word selection:</p><ol><li><p><strong>Knob Settings</strong>:</p><ul><li>Range: 0-500</li><li>Default: 50</li><li>Step: 5</li></ul></li><li><p><strong>Effect</strong>:</p><ul><li>Higher values: Consider more word possibilities</li><li>Lower values: Focus on most likely words</li><li>Setting of 0: Disable top-k filtering</li></ul></li></ol><h3 id="top-p-nucleus-sampling" tabindex="-1">Top P (Nucleus Sampling) <a class="header-anchor" href="#top-p-nucleus-sampling" aria-label="Permalink to &quot;Top P (Nucleus Sampling)&quot;">​</a></h3><p>Controls probability threshold for word selection:</p><ol><li><p><strong>Knob Settings</strong>:</p><ul><li>Range: 0-1000</li><li>Default: 700</li><li>Step: 1</li></ul></li><li><p><strong>Effect</strong>:</p><ul><li>Higher values (700-1000): Consider wider range of words</li><li>Lower values (0-300): Focus on most probable words</li><li>Middle values (300-700): Balanced approach</li></ul></li></ol><h3 id="search-results" tabindex="-1">Search Results <a class="header-anchor" href="#search-results" aria-label="Permalink to &quot;Search Results&quot;">​</a></h3><p>Controls how many search results are used for context:</p><ol><li><p><strong>Knob Settings</strong>:</p><ul><li>Range: 5-60</li><li>Default: 35</li><li>Step: 1</li></ul></li><li><p><strong>Effect</strong>:</p><ul><li>Higher values: More comprehensive but potentially noisy responses</li><li>Lower values: More focused but potentially limited responses</li><li>Optimal setting depends on content volume and complexity</li></ul></li></ol><h3 id="minimum-score" tabindex="-1">Minimum Score <a class="header-anchor" href="#minimum-score" aria-label="Permalink to &quot;Minimum Score&quot;">​</a></h3><p>Sets the relevance threshold for including content:</p><ol><li><p><strong>Knob Settings</strong>:</p><ul><li>Range: 1-500</li><li>Default: 60</li><li>Step: 1</li></ul></li><li><p><strong>Effect</strong>:</p><ul><li>Higher values: Only highly relevant content considered</li><li>Lower values: More content included, possibly less relevant</li><li>Balance based on content quality and query specificity</li></ul></li></ol><h2 id="managing-test-questions" tabindex="-1">Managing Test Questions <a class="header-anchor" href="#managing-test-questions" aria-label="Permalink to &quot;Managing Test Questions&quot;">​</a></h2><p>The Questions Dialog allows you to create and organize test questions that will be used to evaluate AI configurations.</p><h3 id="adding-questions" tabindex="-1">Adding Questions <a class="header-anchor" href="#adding-questions" aria-label="Permalink to &quot;Adding Questions&quot;">​</a></h3><p>To create test questions:</p><ol><li>Click the &quot;Add Question&quot; button at the bottom of the question list</li><li>A new text field appears in the list</li><li>Type your test question into the field</li><li>Questions should be representative of real-world user queries</li><li>Include a variety of question types to test different aspects of AI performance</li></ol><h3 id="organizing-questions" tabindex="-1">Organizing Questions <a class="header-anchor" href="#organizing-questions" aria-label="Permalink to &quot;Organizing Questions&quot;">​</a></h3><p>Test questions can be reordered to create a logical flow:</p><ol><li><p><strong>Moving Questions</strong>:</p><ul><li>Use the up arrow button to move a question higher in the list</li><li>Use the down arrow button to move a question lower in the list</li><li>Questions are processed in the order they appear</li></ul></li><li><p><strong>Question Order Strategy</strong>:</p><ul><li>Group related questions together</li><li>Progress from simple to complex questions</li><li>Include questions that test different capabilities</li></ul></li></ol><h3 id="removing-questions" tabindex="-1">Removing Questions <a class="header-anchor" href="#removing-questions" aria-label="Permalink to &quot;Removing Questions&quot;">​</a></h3><p>To delete test questions:</p><ol><li>Click the red close (×) button next to the question</li><li>The question is immediately removed from the list</li><li>Remember to save changes to make removal permanent</li></ol><h2 id="test-case-operations" tabindex="-1">Test Case Operations <a class="header-anchor" href="#test-case-operations" aria-label="Permalink to &quot;Test Case Operations&quot;">​</a></h2><h3 id="saving-configurations" tabindex="-1">Saving Configurations <a class="header-anchor" href="#saving-configurations" aria-label="Permalink to &quot;Saving Configurations&quot;">​</a></h3><p>To save your test configuration:</p><ol><li><strong>AI Tuning</strong>: Click the &quot;Save Test AI Tuning Prompt&quot; button</li><li><strong>Test Questions</strong>: Click the &quot;SAVE ALL QUESTIONS&quot; button</li><li>A success message confirms when settings are saved</li><li>Both configurations (tuning and questions) must be saved separately</li></ol><h3 id="running-tests" tabindex="-1">Running Tests <a class="header-anchor" href="#running-tests" aria-label="Permalink to &quot;Running Tests&quot;">​</a></h3><p>After configuring both tuning parameters and questions:</p><ol><li>Run tests from the main test case interface</li><li>The system will process each question using: <ul><li>Current production configuration</li><li>Test configuration with your new settings</li></ul></li><li>Results are displayed side-by-side for comparison</li></ol><h3 id="comparing-results" tabindex="-1">Comparing Results <a class="header-anchor" href="#comparing-results" aria-label="Permalink to &quot;Comparing Results&quot;">​</a></h3><p>The comparison view shows:</p><ol><li>Each test question</li><li>The response using production settings</li><li>The response using test settings</li><li>Performance metrics for both responses</li><li>Visual indicators of differences between responses</li></ol><h3 id="promoting-to-production" tabindex="-1">Promoting to Production <a class="header-anchor" href="#promoting-to-production" aria-label="Permalink to &quot;Promoting to Production&quot;">​</a></h3><p>When satisfied with test results:</p><ol><li>Click the &quot;Promote to Production&quot; button</li><li>Confirm the promotion in the dialog that appears</li><li>The test configuration becomes the new production configuration</li><li>Changes take effect immediately</li></ol><h2 id="best-practices" tabindex="-1">Best Practices <a class="header-anchor" href="#best-practices" aria-label="Permalink to &quot;Best Practices&quot;">​</a></h2><p>For effective AI test case configuration:</p><ol><li><p><strong>Systematic Testing</strong>:</p><ul><li>Change one parameter at a time</li><li>Document the impact of each change</li><li>Create multiple test configurations for comparison</li><li>Test across a range of question types</li></ul></li><li><p><strong>Question Development</strong>:</p><ul><li>Include questions that represent real user queries</li><li>Test both simple and complex scenarios</li><li>Include edge cases and potential problem areas</li><li>Use questions that target specific knowledge areas</li></ul></li><li><p><strong>Parameter Tuning</strong>:</p><ul><li>Start with default values</li><li>Make incremental adjustments</li><li>Find the right balance between creativity and accuracy</li><li>Different content types may require different settings</li></ul></li><li><p><strong>System Instructions</strong>:</p><ul><li>Be specific about the AI&#39;s role and limitations</li><li>Provide clear guidance on response style</li><li>Include examples of desired outputs</li><li>Consider user experience and expectations</li></ul></li><li><p><strong>Evaluation Process</strong>:</p><ul><li>Define clear success criteria before testing</li><li>Compare responses objectively</li><li>Look for improvements in accuracy, relevance, and style</li><li>Get feedback from potential users</li></ul></li></ol><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><p><strong>Issue</strong>: Changes not reflected in test results</p><ul><li>Verify that you saved the configuration after making changes</li><li>Check that you&#39;re viewing results from the latest test run</li><li>Try refreshing the page and running the test again</li></ul><p><strong>Issue</strong>: Test case submission error</p><ul><li>Check for error messages in the response</li><li>Verify all required fields are completed</li><li>Ensure parameter values are within acceptable ranges</li><li>Check your network connection</li></ul><p><strong>Issue</strong>: Inconsistent AI responses</p><ul><li>This may be expected with higher randomness settings</li><li>Try lowering the temperature value for more consistency</li><li>Run multiple tests to understand the range of responses</li></ul><p><strong>Issue</strong>: Missing knowledge in responses</p><ul><li>Check the Search Results parameter (try increasing)</li><li>Verify the Minimum Score isn&#39;t too high</li><li>Ensure relevant content exists in the knowledge base</li><li>Review system instructions for any limitations</li></ul><p><strong>Issue</strong>: Responses too generic or vague</p><ul><li>Increase the Minimum Score parameter</li><li>Decrease the number of Search Results</li><li>Add more specific guidance in system instructions</li><li>Review test questions for clarity</li></ul><p><strong>Issue</strong>: Cannot save questions</p><ul><li>Ensure you&#39;re clicking the &quot;SAVE ALL QUESTIONS&quot; button</li><li>Check for any validation errors</li><li>Verify you have the necessary permissions</li><li>Try refreshing the page and attempting again</li></ul><hr><p>For additional assistance with AI test case configuration, please contact your system administrator or refer to the platform documentation.</p>',80)]))}const d=i(n,[["render",a]]);export{p as __pageData,d as default};
